<?php require 'config/config.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]); if(isset($_POST['update']))foreach($_POST['qty']??[] as $id=>$q)$_SESSION['cart'][(int)$id]=max(0,(int)$q); flash('success','Cart updated.');redirect('cart.php');}
$cart=$_SESSION['cart']??[];$items=[];$total=0;
if($cart){$ids=array_keys($cart);$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN ($in)");$s->execute($ids);foreach($s as $p){$q=min((int)$cart[$p['id']],(int)$p['stock_quantity']);$items[]=['p'=>$p,'q'=>$q,'line'=>$q*$p['price']];$total+=$q*$p['price'];}}
layout_header('Cart');?>
<h2>Your Cart</h2><?php if(!$items):?><div class="alert alert-info">Your cart is empty. <a href="products.php">Browse products</a>.</div><?php else:?><form method="post"><?=csrf_field()?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $i):$p=$i['p'];?><tr><td><?=e($p['name'])?></td><td><?=money((float)$p['price'])?></td><td><input class="form-control" style="width:90px" type="number" min="0" max="<?=$p['stock_quantity']?>" name="qty[<?=$p['id']?>]" value="<?=$i['q']?>"></td><td><?=money((float)$i['line'])?></td><td><button name="remove" value="<?=$p['id']?>" class="btn btn-sm btn-outline-danger">Remove</button></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex justify-content-between"><button name="update" class="btn btn-outline-secondary">Update cart</button><h4>Total: <?=money((float)$total)?></h4></div></form><a class="btn btn-success mt-3 float-end" href="checkout.php">Continue to pickup</a><?php endif;?>
<?php layout_footer(); ?>